# Edit only the original CN421 Label Library workbook envelope exported by EBPro.
# The caller exports the complete current library and imports the edited copy.
function Read-WeinviewLabelWorkbook([string]$Path) {
 Add-Type -AssemblyName System.IO.Compression.FileSystem
 $zip=[IO.Compression.ZipFile]::OpenRead([IO.Path]::GetFullPath($Path))
 try {
  function EntryText([string]$Name) {$entry=$zip.GetEntry($Name);if(!$entry -or $entry.Length -gt 8MB){throw ('Native label workbook entry unavailable: '+$Name)};$reader=New-Object IO.StreamReader($entry.Open(),[Text.Encoding]::UTF8,$true);try{return $reader.ReadToEnd()}finally{$reader.Dispose()}}
  [xml]$book=EntryText 'xl/workbook.xml';[xml]$strings=EntryText 'xl/sharedStrings.xml';[xml]$sheet=EntryText 'xl/worksheets/sheet1.xml'
  $ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';$names=New-Object Xml.XmlNamespaceManager($sheet.NameTable);$names.AddNamespace('m',$ns)
  $sheets=@($book.GetElementsByTagName('sheet',$ns));if($sheets.Count -ne 1 -or $sheets[0].GetAttribute('name') -cne '标签'){throw 'Original one-sheet CN421 Label Library export required'}
  $si=@($strings.GetElementsByTagName('si',$ns));$texts=@(foreach($item in $si){$parts=@($item.GetElementsByTagName('t',$ns));if($parts.Count -ne 1){throw 'Native label workbook shared string shape changed'};[string]$parts[0].InnerText})
  $rows=@($sheet.SelectNodes('/m:worksheet/m:sheetData/m:row',$names));if($rows.Count -lt 2){throw 'Native label workbook needs header and at least one original row'}
  function CellText($Cell) {if($Cell.GetAttribute('t') -cne 's'){throw 'Native label workbook non-shared-string cell changed'};$v=$Cell.SelectSingleNode('m:v',$names);$index=0;if(!$v -or ![int]::TryParse($v.InnerText,[ref]$index) -or $index -lt 0 -or $index -ge $texts.Count){throw 'Native label workbook string index invalid'};return [string]$texts[$index]}
  $headers=[ordered]@{};foreach($cell in @($rows[0].SelectNodes('m:c',$names))){$ref=$cell.GetAttribute('r');if($ref -cnotmatch '^([A-Z]+)1$' -or $headers.Contains($Matches[1])){throw 'Native label header cell address changed'};$headers[$Matches[1]]=CellText $cell}
  if($headers['A'] -cne '文字标签名称' -or $headers['B'] -cne '描述'){throw 'Native label header names changed'}
  $columns=@();foreach($key in @($headers.Keys|Where-Object {$_ -cnotin @('A','B')})){$match=[regex]::Match($headers[$key],'^Language ([1-9][0-9]?), 状态 ([0-9]{1,3})$');if(!$match.Success){throw ('Unknown native label language/state column: '+$headers[$key])};$columns+=@{column=$key;language=[int]$match.Groups[1].Value;state=[int]$match.Groups[2].Value;header=$headers[$key]}}
  if($columns.Count -lt 1 -or $columns.Count -gt 6144){throw 'Native label grid size invalid'}
  $labels=@();$seen=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
  foreach($row in @($rows|Select-Object -Skip 1)){$data=@{};foreach($cell in @($row.SelectNodes('m:c',$names))){$ref=$cell.GetAttribute('r');if($ref -cnotmatch '^([A-Z]+)[0-9]+$' -or !$headers.Contains($Matches[1])){throw 'Native label row cell address changed'};$data[$Matches[1]]=CellText $cell};if(!$data.ContainsKey('A') -or !$data['A'] -or !$seen.Add($data['A'])){throw 'Native label name missing or duplicate'};$labels+=@{name=$data['A'];description=if($data.ContainsKey('B')){$data['B']}else{''};cells=$data;row=[int]$row.GetAttribute('r')}}
  return @{path=[IO.Path]::GetFullPath($Path);sha256=(Get-FileHash -LiteralPath $Path).Hash;headers=$headers;columns=$columns;labels=$labels;sheet=$sheet;shared_strings=$strings;namespace=$ns;namespace_manager=$names}
 }finally{$zip.Dispose()}
}
function Write-WeinviewLabelWorkbook([string]$Source,[string]$Output,$Labels,[int]$LanguageCount) {
 if($LanguageCount -lt 1 -or $LanguageCount -gt 24){throw 'Actual project language count1..24 required'}
 $sourcePath=[IO.Path]::GetFullPath($Source);$outputPath=[IO.Path]::GetFullPath($Output)
 if($sourcePath -ieq $outputPath -or (Test-Path -LiteralPath $outputPath)){throw 'Fresh separate label workbook output required'}
 $book=Read-WeinviewLabelWorkbook $sourcePath;$all=@($Labels);if($all.Count -lt 1 -or $all.Count -gt 1000){throw 'One to1000 label updates required'}
 $seen=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
 $requested=@{};foreach($label in $all){if($label.name -isnot [string] -or !$label.name.Trim() -or $label.name.Length -gt 64 -or $label.name -match '[\x00-\x1f\x7f]' -or !$seen.Add($label.name)){throw 'Invalid or repeated label name'};$states=@($label.states);if($states.Count -lt 1 -or $states.Count -gt 256){throw 'Native label state count outside1..256'};$stateSeen=New-Object 'Collections.Generic.HashSet[int]';foreach($state in $states){$stateNumber=0;if(![int]::TryParse([string]$state.state,[ref]$stateNumber) -or $stateNumber -lt 0 -or $stateNumber -gt 255 -or !$stateSeen.Add($stateNumber)){throw 'Invalid or repeated label state'};$slotTexts=@($state.texts);if($slotTexts.Count -gt $LanguageCount){throw 'Texts exceed current project language slots'};for($l=0;$l -lt $slotTexts.Count;$l++){if($null -ne $slotTexts[$l] -and ($slotTexts[$l] -isnot [string] -or $slotTexts[$l].Length -gt 4096 -or $slotTexts[$l] -match '[\x00-\x08\x0B\x0C\x0E-\x1F]')){throw 'Invalid label text'}}};$requested[$label.name]=$label}
 foreach($label in $all){foreach($state in @($label.states)){$s=[int]$state.state;$slotTexts=@($state.texts);for($l=1;$l -le $slotTexts.Count;$l++){if($null -ne $slotTexts[$l-1] -and @($book.columns|Where-Object {$_.state -eq $s -and $_.language -eq $l}).Count -ne 1){throw ('Original export lacks requested column Language '+$l+' state '+$s)}}}}
 $ns=$book.namespace;$doc=$book.sheet;$strings=$book.shared_strings;$names=$book.namespace_manager
 $items=@($strings.GetElementsByTagName('si',$ns));$values=New-Object 'Collections.Generic.Dictionary[string,int]' ([StringComparer]::Ordinal)
 for($i=0;$i -lt $items.Count;$i++){$value=[string]$items[$i].InnerText;if(!$values.ContainsKey($value)){$values.Add($value,$i)}}
 function StringIndex([string]$Value){if($values.ContainsKey($Value)){return $values[$Value]};$index=$strings.DocumentElement.ChildNodes.Count;$si=$strings.CreateElement('si',$ns);$t=$strings.CreateElement('t',$ns);$t.InnerText=$Value;$null=$si.AppendChild($t);$null=$strings.DocumentElement.AppendChild($si);$values.Add($Value,$index);return $index}
 $sheetData=$doc.SelectSingleNode('/m:worksheet/m:sheetData',$names);$rows=@($sheetData.SelectNodes('m:row',$names));$byName=@{};foreach($item in $book.labels){$byName[$item.name]=$item.row}
 foreach($label in $all){$rowNumber=0;$existing=$byName.ContainsKey($label.name);if($existing){$rowNumber=$byName[$label.name];$row=@($rows|Where-Object {[int]$_.GetAttribute('r') -eq $rowNumber})[0]}else{$rowNumber=$rows.Count+1;$row=$rows[-1].CloneNode($true);$row.SetAttribute('r',[string]$rowNumber);foreach($c in @($row.SelectNodes('m:c',$names))){$old=$c.GetAttribute('r');$c.SetAttribute('r',($old -replace '[0-9]+$',[string]$rowNumber));$c.SelectSingleNode('m:v',$names).InnerText=[string](StringIndex '')};$null=$sheetData.AppendChild($row);$rows+=,$row;$byName[$label.name]=$rowNumber}
  $updates=@{A=[string]$label.name};$hasDescription=if($label -is [Collections.IDictionary]){$label.Contains('description')}else{$label.PSObject.Properties.Name -contains 'description'};if($hasDescription){$updates.B=[string]$label.description}elseif(!$existing){$updates.B=''}
  foreach($state in @($label.states)){$s=[int]$state.state;$slotTexts=@($state.texts);foreach($column in $book.columns){if($column.state -eq $s -and $column.language -le $slotTexts.Count -and $null -ne $slotTexts[$column.language-1]){$updates[$column.column]=[string]$slotTexts[$column.language-1]}}}
  foreach($key in $updates.Keys){$ref=$key+[string]$rowNumber;$cell=@($row.SelectNodes('m:c',$names)|Where-Object {$_.GetAttribute('r') -ceq $ref});if($cell.Count -ne 1){throw ('Native label template lacks cell '+$ref)};$cell[0].SelectSingleNode('m:v',$names).InnerText=[string](StringIndex $updates[$key])}
 }
 $strings.DocumentElement.SetAttribute('uniqueCount',[string]$strings.DocumentElement.ChildNodes.Count);$total=0;foreach($row in @($sheetData.SelectNodes('m:row',$names))){$total+=@($row.SelectNodes('m:c',$names)).Count};$strings.DocumentElement.SetAttribute('count',[string]$total)
 [IO.File]::Copy($sourcePath,$outputPath,$false)
 $zip=[IO.Compression.ZipFile]::Open($outputPath,[IO.Compression.ZipArchiveMode]::Update)
 try{foreach($part in @(@('xl/sharedStrings.xml',$strings),@('xl/worksheets/sheet1.xml',$doc))){$old=$zip.GetEntry($part[0]);if(!$old){throw 'Original workbook part missing during write'};$old.Delete();$entry=$zip.CreateEntry($part[0],[IO.Compression.CompressionLevel]::Optimal);$writer=New-Object IO.StreamWriter($entry.Open(),(New-Object Text.UTF8Encoding($false)));try{$writer.Write($part[1].OuterXml)}finally{$writer.Dispose()}}}finally{$zip.Dispose()}
 $after=Read-WeinviewLabelWorkbook $outputPath;foreach($label in $all){$matches=@($after.labels|Where-Object {$_.name -ceq $label.name});if($matches.Count -ne 1){throw 'Written label missing in workbook'}}
 $preserved=@($book.labels|Where-Object {!$requested.ContainsKey($_.name)}|ForEach-Object {$_.name})
 foreach($old in @($book.labels)){$new=@($after.labels|Where-Object {$_.name -ceq $old.name});if($new.Count -ne 1){throw 'Existing native label lost during merge'};foreach($key in $old.cells.Keys){$explicit=$false;if($requested.ContainsKey($old.name)){if($key -ceq 'A'){$explicit=$true};if($key -ceq 'B'){$item=$requested[$old.name];$explicit=if($item -is [Collections.IDictionary]){$item.Contains('description')}else{$item.PSObject.Properties.Name -contains 'description'}};foreach($state in @($requested[$old.name].states)){foreach($column in $book.columns){if($column.column -ceq $key -and $column.state -eq [int]$state.state -and $column.language -le @($state.texts).Count -and $null -ne @($state.texts)[$column.language-1]){$explicit=$true}}}};if(!$explicit -and $new[0].cells[$key] -cne $old.cells[$key]){throw ('Unspecified native label cell changed: '+$old.name+'/'+$key)}}}
 return @{path=$outputPath;sha256=$after.sha256;label_count=$after.labels.Count;original_labels=@($book.labels|ForEach-Object {$_.name});updated_labels=@($all|ForEach-Object {$_.name});preserved_existing_labels=$true;preserved_unmentioned_labels=$preserved;merge_mode='explicit-state-and-nonnull-slot-only';columns=@($after.columns)}
}
